const trig = $('Sub-workflow Input').first()?.json || {};
const ctx = $('Resolve Tenant Context').first()?.json || {};
const scope = String(trig.scope || 'list').toLowerCase();
const query = String(trig.query || '').trim();
const limit = Math.min(parseInt(trig.limit, 10) || 10, 50);
const envelope = {
  ok: false, status: 'refused', reasonCode: 'none', guidance: 'none', userMessage: null,
  connectorId: 'microsoft.outlook', organizationId: ctx.organizationId || null, userId: ctx.userId || null,
  contextSource: ctx.contextSource || 'fallback', degraded: ctx.degraded === true,
  records: [], total: 0, error: null,
  diagnostics: { requestId: 'out-' + ($execution.id || 'na') + '-' + Date.now(), workflow: 'prism-10-outlook-service', scope: scope }
};
function refuse(code, msg, guidance) { envelope.status = 'refused'; envelope.reasonCode = code; envelope.userMessage = msg; envelope.guidance = guidance; return [{ json: envelope }]; }
if (ctx.enabled === false) return refuse('connector_disabled', 'Outlook Mail is turned off for you - enable it in Connections.', 'enable');
if (ctx.entitlement === false) return refuse('not_entitled', 'Your account does not have access to Outlook Mail - ask your admin to unlock it.', 'request_access');
if (!ctx.accessToken) return refuse('missing_token', 'Outlook Mail is not connected yet - connect your Microsoft account in Connections to see your mail.', 'connect');
let url = 'https://graph.microsoft.com/v1.0/me/messages?$top=' + limit + '&$select=id,subject,from,receivedDateTime,bodyPreview,hasAttachments,webLink,conversationId';
if (scope === 'search') {
  if (!query) return refuse('empty', 'Provide a search term to search your mail.', 'none');
  url = 'https://graph.microsoft.com/v1.0/me/messages?$search=' + String.fromCharCode(34) + encodeURIComponent(query) + String.fromCharCode(34) + '&$top=' + limit + '&$select=id,subject,from,receivedDateTime,bodyPreview,hasAttachments,webLink,conversationId';
}
if (scope === 'thread') {
  if (!query) return refuse('empty', 'Provide a conversation id to fetch a thread.', 'none');
  url = 'https://graph.microsoft.com/v1.0/me/messages?$filter=conversationId eq ' + String.fromCharCode(34) + encodeURIComponent(query) + String.fromCharCode(34) + '&$top=' + limit + '&$select=id,subject,from,receivedDateTime,bodyPreview,hasAttachments,webLink,conversationId';
}
return [{ json: Object.assign({}, envelope, { ok: true, status: 'pending', accessToken: ctx.accessToken, requestUrl: url, searchMode: scope === 'search' }) }];

const res = $input.first()?.json || {};
const meta = $('Gate & Build Request').first()?.json || {};
const envelope = {
  ok: false, status: 'error', reasonCode: 'provider_error', guidance: 'retry', userMessage: 'Microsoft Outlook returned an error - try again shortly. If it persists, reconnect Outlook in Connections.',
  connectorId: 'microsoft.outlook', organizationId: meta.organizationId || null, userId: meta.userId || null,
  contextSource: meta.contextSource || 'fallback', degraded: meta.degraded === true,
  records: [], total: 0, error: null,
  diagnostics: { requestId: meta.diagnostics ? meta.diagnostics.requestId : ('out-' + Date.now()), workflow: 'prism-10-outlook-service' }
};
const httpStatus = (res.error && (res.error.status || res.error.statusCode)) || res.statusCode || null;
const graphCode = res.error && res.error.code ? String(res.error.code) : '';
if (res.error && !Array.isArray(res.value)) {
  envelope.error = { provider: 'microsoft', httpStatus: httpStatus || null, message: graphCode || String(res.error.message || 'graph_error'), retryable: (httpStatus || 0) >= 500 || httpStatus === 429 };
  if (httpStatus === 429) { envelope.reasonCode = 'rate_limited'; envelope.userMessage = 'Microsoft is rate-limiting requests right now - try again in a moment.'; }
  else if (httpStatus === 401 || graphCode.indexOf('InvalidAuthenticationToken') >= 0) { envelope.reasonCode = 'reauth_required'; envelope.guidance = 'reconnect'; envelope.userMessage = 'Your Outlook connection needs re-authentication - reconnect in Connections.'; }
  else if (httpStatus === 403) { envelope.reasonCode = 'not_entitled'; envelope.guidance = 'request_access'; envelope.userMessage = 'Your account does not have permission for this mailbox data - ask your admin.'; }
  return [{ json: envelope }];
}
const raw = Array.isArray(res.value) ? res.value : [];
const records = raw.map(function (m) { return {
  id: String(m.id || ''), subject: m.subject || '(no subject)', from: m.from && m.from.emailAddress ? m.from.emailAddress.address : '',
  fromName: m.from && m.from.emailAddress ? m.from.emailAddress.name : '', receivedDateTime: m.receivedDateTime || '',
  preview: m.bodyPreview || '', hasAttachments: m.hasAttachments === true, conversationId: m.conversationId || '', webLink: m.webLink || ''
}; });
envelope.ok = true; envelope.status = 'success'; envelope.reasonCode = 'none'; envelope.guidance = 'none'; envelope.userMessage = null;
envelope.records = records; envelope.total = records.length;
envelope.error = null;
return [{ json: envelope }];
